// Tests for the pull-request quality report (lesson 11.4).
import { describe, it, expect } from 'vitest';
import { mutationScore, qualityReport } from './quality.js';

const stryker = (...statuses) => ({ files: { 'a.js': { mutants: statuses.map((status) => ({ status })) } } });

// Starter: ONE smoke test — it only checks that the code under test can be imported. It kills no mutant.
// Write the real tests below (see the task). Khởi đầu: MỘT test khói — chỉ kiểm code nạp được, không diệt đột biến nào.
describe('starter', () => {
  it('the code under test can be imported', () => {
    expect(mutationScore).toBeDefined();
    expect(qualityReport).toBeDefined();
  });
});

// Rules every LabFlow Lite workflow must follow (lessons 9.1–9.4, graded in Lab 9 by scripts/cham-lab-9.mjs).
// Each rule reads the parsed YAML and says ok or why not. actionlint checks that a workflow is VALID;
// these rules check that it is SAFE: a red test must turn the required check red, and only a real bug may do that.
import { parse } from 'yaml';

const steps = (job) => job.steps ?? [];
const runs = (job) => steps(job).filter((s) => typeof s.run === 'string').map((s) => s.run);
const setupNode = (job) => steps(job).filter((s) => typeof s.uses === 'string' && s.uses.startsWith('actions/setup-node@'));
const nameOf = (id, job) => String(job.name ?? id);
const reportOnly = (job) => job['continue-on-error'] === true;
const needsOf = (job) => [job.needs ?? []].flat();
const gateOf = (jobs) => Object.entries(jobs).find(([id, job]) => nameOf(id, job) === 'ci-ok');

const RULES = [
  ['R1', 'npm ci, never npm install', (jobs) => {
    const bad = Object.entries(jobs).filter(([, j]) => runs(j).some((r) => /\bnpm (install|i)\b/.test(r))).map(([id]) => id);
    return bad.length ? 'npm install in: ' + bad.join(', ') + ' (it may change package-lock.json; CI must install exactly the lockfile)' : '';
  }],
  ['R2', 'setup-node caches the npm downloads', (jobs) => {
    const bad = Object.entries(jobs).filter(([, j]) => setupNode(j).some((s) => s.with?.cache !== 'npm')).map(([id]) => id);
    return bad.length ? 'no cache: npm in: ' + bad.join(', ') : '';
  }],
  ['R3', 'integration tests get a healthy PostgreSQL service', (jobs) => {
    const found = Object.entries(jobs).filter(([, j]) => runs(j).some((r) => r.includes('test:int')));
    if (!found.length) return 'no job runs npm run test:int';
    for (const [id, job] of found) {
      const pg = Object.values(job.services ?? {}).find((s) => /^postgres:17\b/.test(String(s.image)));
      if (!pg) return id + ': no postgres:17 service';
      if (!String(pg.options ?? '').includes('--health-cmd')) return id + ': the service has no --health-cmd, tests may start before PostgreSQL is ready';
      const url = String(job.env?.TEST_DATABASE_URL ?? steps(job).map((s) => s.env?.TEST_DATABASE_URL).find(Boolean) ?? '');
      const hostPorts = (pg.ports ?? []).map((p) => String(p).split(':')[0]);
      if (!hostPorts.some((p) => url.includes('@localhost:' + p + '/'))) return id + ': TEST_DATABASE_URL must reach the service at localhost:<published port>, got "' + url + '"';
    }
    return '';
  }],
  ['R4', 'Playwright browsers come with their system libraries', (jobs) => {
    const bad = Object.entries(jobs).filter(([, j]) => runs(j).some((r) => r.includes('playwright install') && !r.includes('--with-deps'))).map(([id]) => id);
    return bad.length ? 'playwright install without --with-deps in: ' + bad.join(', ') : '';
  }],
  ['R5', 'one gate job named exactly ci-ok', (jobs) => {
    const gate = gateOf(jobs);
    if (!gate) return 'no job is named ci-ok — branch protection needs one stable name to require';
    return /\$\{\{/.test(String(gate[1].name ?? '')) ? 'the gate name contains an expression' : '';
  }],
  ['R6', 'the gate runs even when a job it needs failed', (jobs) => {
    const gate = gateOf(jobs);
    if (!gate) return 'no ci-ok job';
    if (!/always\(\)|!\s*cancelled\(\)/.test(String(gate[1].if ?? ''))) return 'ci-ok has no if: always() — it is SKIPPED when a job fails, and a skipped required check counts as passed';
    const text = JSON.stringify(gate[1]);
    return text.includes('ci-gate.mjs') || /needs\.[\w*-]+\.result|contains\(needs/.test(text) ? '' : 'ci-ok never looks at the results of the jobs it needs';
  }],
  ['R7', 'every blocking job is required; report-only jobs never block', (jobs) => {
    const gate = gateOf(jobs);
    if (!gate) return 'no ci-ok job';
    const needs = needsOf(gate[1]);
    const others = Object.entries(jobs).filter(([id]) => id !== gate[0]);
    const missing = others.filter(([id, j]) => !reportOnly(j) && !needs.includes(id)).map(([id]) => id);
    if (missing.length) return 'ci-ok does not need: ' + missing.join(', ');
    const blocking = needs.filter((id) => jobs[id] && reportOnly(jobs[id]));
    if (blocking.length) return 'ci-ok needs report-only jobs: ' + blocking.join(', ');
    const flaky = others.filter(([, j]) => !reportOnly(j) && runs(j).some((r) => r.includes('test:quarantine'))).map(([id]) => id);
    return flaky.length ? 'quarantined tests run in a blocking job: ' + flaky.join(', ') : '';
  }],
  ['R8', 'a red matrix leg makes the job red', (jobs, { minNode }) => {
    for (const [id, job] of Object.entries(jobs)) {
      const matrix = job.strategy?.matrix;
      if (!matrix) continue;
      if (reportOnly(job)) return id + ': continue-on-error: true hides every red leg of the matrix';
      const old = [matrix.node ?? []].flat().filter((v) => Number.parseInt(v, 10) < minNode);
      if (old.length) return id + ': Node ' + old.join(', ') + ' is below engines (>= ' + minNode + ')';
    }
    return '';
  }],
];

export function checkWorkflow(text, { minNode = 22 } = {}) {
  const jobs = parse(text)?.jobs ?? {};
  return RULES.map(([id, title, rule]) => {
    const why = rule(jobs, { minNode });
    return { id, title, ok: why === '', why };
  });
}

// The one quality report of a pull request (lesson 11.4): every layer's tests, coverage, mutation score and traceability
// on one page — and the list of problems that make the "report" job (and so ci-ok) red.
import { coverageTable } from './summary.js';
import { rtmMarkdown } from './rtm.js';

// Stryker's JSON report → score in %, the way Stryker counts it: (killed + timeout) / every mutant that could run.
export function mutationScore(report) {
  let detected = 0;
  let valid = 0;
  for (const file of Object.values(report.files)) {
    for (const m of file.mutants) {
      if (['CompileError', 'RuntimeError', 'Ignored'].includes(m.status)) continue;
      valid++;
      if (m.status === 'Killed' || m.status === 'Timeout') detected++;
    }
  }
  return valid === 0 ? 0 : Math.round((detected / valid) * 10000) / 100;
}

// suites: [{ label, tests: [{ passed }] | null }] — null means the report is missing (the job did not run or crashed).
export function qualityReport({ title, suites, coverage, thresholds, mutation, mutationBreak, rtm }) {
  const problems = [];
  const rows = suites.map(({ label, tests }) => {
    if (!tests) { problems.push(label + ': no report'); return '| ' + label + ' | — | — | ⚠️ no report |'; }
    const failed = tests.filter((t) => !t.passed).length;
    if (failed) problems.push(label + ': ' + failed + ' failed');
    if (tests.length === 0) problems.push(label + ': 0 tests');
    return '| ' + label + ' | ' + tests.length + ' | ' + failed + ' | ' + (failed || tests.length === 0 ? '❌' : '✅') + ' |';
  });
  for (const m of Object.keys(thresholds)) {
    if (coverage && coverage.total[m].pct < thresholds[m]) problems.push('coverage ' + m + ' ' + coverage.total[m].pct + '% < ' + thresholds[m] + '%');
  }
  if (!coverage) problems.push('coverage: no report');
  if (mutation === null) problems.push('mutation: no report');
  else if (mutation < mutationBreak) problems.push('mutation score ' + mutation + '% < ' + mutationBreak + '%');
  problems.push(...rtm.gaps.map((g) => 'traceability — ' + g));

  const parts = [
    '## ' + title,
    problems.length ? '### ❌ Do not merge\n\n' + problems.map((p) => '- ' + p).join('\n') : '### ✅ Every check passed',
    ['| Layer | Tests | Failed | |', '|---|---:|---:|---|', ...rows].join('\n'),
    coverage ? coverageTable(coverage, thresholds) : '',
    '**Mutation score:** ' + (mutation === null ? '—' : mutation + '%') + ' (minimum ' + mutationBreak + '%)',
    '### Traceability\n\n' + rtmMarkdown(rtm.rows, rtm.gaps).trim(),
  ];
  return { markdown: parts.filter(Boolean).join('\n\n') + '\n', problems };
}

// Requirements traceability matrix (lesson 11.1): which passing tests prove which requirement, at which layer.
// The convention: a test proves a requirement when its full name (describe titles + test title) carries the requirement's id —
// "BR-04", "Lite-3", or "US-11" followed by acceptance criteria ("AC2", "AC2–AC5", "AC4, AC5").
export const LAYERS = ['Unit', 'API', 'DB', 'UI', 'E2E'];

export function layerOf(file) {
  if (/(^|\/)src\/ci\//.test(file)) return null;   // tests of the CI tooling itself — their names quote ids as DATA (lesson 11.4)
  if (/(^|\/)src\/api\//.test(file)) return 'API';
  if (/(^|\/)test\/integration\//.test(file)) return 'DB';
  if (/(^|\/)web\//.test(file)) return 'UI';
  if (/(^|\/)e2e\//.test(file)) return 'E2E';
  return 'Unit';
}

export function tagsOf(name) {
  const tags = new Set(name.match(/\b(BR-\d{2}|Lite-\d+)\b/g) ?? []);
  const story = /\bUS-11\b(.*)/.exec(name);
  if (story) {
    for (const [, from, to] of story[1].matchAll(/\bAC(\d+)(?:\s*[–-]\s*AC(\d+))?/g)) {
      for (let n = Number(from); n <= Number(to ?? from); n++) tags.add('US-11 AC' + n);
    }
  }
  return [...tags];
}

// Vitest --reporter=json → [{ file, name, passed }]; root is cut from absolute paths.
export function testsFromVitest(report, root = '') {
  return report.testResults.flatMap((f) => f.assertionResults.map((t) => ({
    file: f.name.startsWith(root) ? f.name.slice(root.length).replace(/^\//, '') : f.name,
    name: t.fullName,
    passed: t.status === 'passed',
  })));
}

// Playwright --reporter=json → the same shape (the "setup" project is not a test of the product).
export function testsFromPlaywright(report) {
  const out = [];
  const walk = (suite, titles) => {
    for (const spec of suite.specs ?? []) {
      for (const t of spec.tests.filter((x) => x.projectName !== 'setup')) {
        out.push({ file: spec.file, name: [...titles, spec.title].join(' '), passed: t.status === 'expected' || t.status === 'flaky' });
      }
    }
    for (const child of suite.suites ?? []) walk(child, [...titles, child.title]);
  };
  for (const fileSuite of report.suites) walk(fileSuite, []);   // the top-level suites are the files
  return out;
}

export function buildMatrix(requirements, tests) {
  return requirements.map((r) => {
    const counts = Object.fromEntries(LAYERS.map((l) => [l, 0]));
    for (const t of tests) if (t.passed && layerOf(t.file) && tagsOf(t.name).includes(r.id)) counts[layerOf(t.file)]++;
    return { ...r, counts, total: LAYERS.reduce((n, l) => n + counts[l], 0) };
  });
}

// The gate: every in-scope requirement has a passing test; a High-risk one has one above the Unit layer.
export function traceGaps(rows) {
  const gaps = [];
  for (const r of rows.filter((x) => x.inScope)) {
    if (r.total === 0) gaps.push(r.id + ': no passing test');
    else if (r.risk === 'High' && r.total === r.counts.Unit) gaps.push(r.id + ': High risk, tested only at the Unit layer');
  }
  return gaps;
}

export function rtmMarkdown(rows, gaps) {
  const head = ['| Requirement | Risk | ' + LAYERS.join(' | ') + ' | |', '|---|---|' + LAYERS.map(() => '---:|').join('') + '---|'];
  const body = rows.map((r) => '| ' + r.id + (r.inScope ? '' : ' (out of scope)') + ' | ' + r.risk + ' | ' +
    LAYERS.map((l) => (r.counts[l] || '·')).join(' | ') + ' | ' + (!r.inScope ? '—' : gaps.some((g) => g.startsWith(r.id + ':')) ? '❌' : '✅') + ' |');
  const tail = gaps.length ? ['', '**Gaps:**', ...gaps.map((g) => '- ' + g)] : ['', 'Every in-scope requirement is traced to a passing test.'];
  return [...head, ...body, ...tail].join('\n') + '\n';
}

// Turns the Vitest JSON report and the coverage summary into the Markdown GitHub shows on the run page
// (lesson 9.2: written to $GITHUB_STEP_SUMMARY by scripts/ci-summary.mjs).
const METRICS = ['lines', 'branches', 'functions', 'statements'];

// report = Vitest --reporter=json output; root = the project folder, removed from file paths.
export function testHeadline(report) {
  const { numTotalTests: total, numPassedTests: passed, numFailedTests: failed, numPendingTests: skipped } = report;
  if (failed > 0) return '### ❌ ' + failed + ' of ' + total + ' tests failed';
  return '### ✅ ' + passed + ' of ' + total + ' tests passed' + (skipped ? ' (' + skipped + ' skipped)' : '');
}

export function failedTests(report, root = '') {
  const lines = [];
  for (const file of report.testResults) {
    for (const t of file.assertionResults) {
      if (t.status !== 'failed') continue;
      const where = file.name.startsWith(root) ? file.name.slice(root.length).replace(/^\//, '') : file.name;
      const why = (t.failureMessages[0] ?? '').split('\n')[0];
      lines.push('- `' + where + '` › ' + t.fullName + ' — ' + why);
    }
  }
  return lines.join('\n');
}

// summary = coverage/coverage-summary.json; thresholds = the same numbers as vitest.config.js.
export function coverageTable(summary, thresholds) {
  const rows = METRICS.map((m) => {
    const pct = summary.total[m].pct;
    const min = thresholds[m] ?? 0;
    return '| ' + m + ' | ' + pct.toFixed(2) + '% | ' + min + '% | ' + (pct >= min ? '✅' : '❌ below the minimum') + ' |';
  });
  return ['| Coverage | Now | Minimum | |', '|---|---:|---:|---|', ...rows].join('\n');
}

// Several reports (unit + web) → one: counts add up, test files are listed together.
export function mergeReports(reports) {
  const sum = (key) => reports.reduce((n, r) => n + r[key], 0);
  return {
    numTotalTests: sum('numTotalTests'), numPassedTests: sum('numPassedTests'),
    numFailedTests: sum('numFailedTests'), numPendingTests: sum('numPendingTests'),
    testResults: reports.flatMap((r) => r.testResults),
  };
}

export function stepSummary({ title, report, coverage, thresholds, root }) {
  const parts = ['## ' + title, testHeadline(report)];
  const failed = failedTests(report, root);
  if (failed) parts.push(failed);
  if (coverage) parts.push(coverageTable(coverage, thresholds));
  return parts.join('\n\n') + '\n';
}

