// Tests for the pull-request quality report (lesson 11.4).
import { describe, it, expect } from 'vitest';
import { mutationScore, qualityReport } from './quality.js';

const stryker = (...statuses) => ({ files: { 'a.js': { mutants: statuses.map((status) => ({ status })) } } });

describe('mutationScore', () => {
  it('counts killed and timed-out mutants as detected, the way Stryker does', () => {
    expect(mutationScore(stryker('Killed', 'Killed', 'Timeout', 'Survived'))).toBe(75);
    expect(mutationScore(stryker('Killed', 'NoCoverage'))).toBe(50);
  });
  it('leaves out mutants that could not run; nothing to run → 0', () => {
    expect(mutationScore(stryker('Killed', 'CompileError', 'RuntimeError', 'Ignored'))).toBe(100);
    expect(mutationScore(stryker())).toBe(0);
  });
  it('rounds to two decimals: 427 + 2 of 433 → 99.08', () => {
    expect(mutationScore(stryker(...Array(427).fill('Killed'), 'Timeout', 'Timeout', 'Survived', 'Survived', 'Survived', 'Survived'))).toBe(99.08);
  });
});

describe('qualityReport', () => {
  const pass = { passed: true };
  const coverage = { total: { lines: { pct: 98.87 }, branches: { pct: 92.62 }, functions: { pct: 97.39 }, statements: { pct: 98.22 } } };
  const thresholds = { lines: 97, branches: 91, functions: 96, statements: 97 };
  const ok = { title: 'Q', suites: [{ label: 'Unit', tests: [pass, pass] }, { label: 'E2E', tests: [pass] }], coverage, thresholds, mutation: 99.08, mutationBreak: 95, rtm: { rows: [], gaps: [] } };

  it('all good → no problems, a green headline and every section', () => {
    const { markdown, problems } = qualityReport(ok);
    expect(problems).toEqual([]);
    expect(markdown).toContain('### ✅ Every check passed');
    expect(markdown).toContain('| Unit | 2 | 0 | ✅ |');
    expect(markdown).toContain('**Mutation score:** 99.08% (minimum 95%)');
    expect(markdown).toContain('| lines | 98.87% | 97% | ✅ |');
  });

  it('lists every reason not to merge', () => {
    const { markdown, problems } = qualityReport({
      ...ok,
      suites: [{ label: 'Unit', tests: [pass, { passed: false }] }, { label: 'DB', tests: null }, { label: 'UI', tests: [] }],
      coverage: { total: { ...coverage.total, branches: { pct: 90.5 } } },
      mutation: 94.99,
      rtm: { rows: [], gaps: ['Lite-3: High risk, tested only at the Unit layer'] },
    });
    expect(problems).toEqual(['Unit: 1 failed', 'DB: no report', 'UI: 0 tests', 'coverage branches 90.5% < 91%',
      'mutation score 94.99% < 95%', 'traceability — Lite-3: High risk, tested only at the Unit layer']);
    expect(markdown).toContain('### ❌ Do not merge');
    expect(markdown).toContain('| DB | — | — | ⚠️ no report |');
  });

  it('a missing coverage or mutation report is a problem, not a pass', () => {
    const { problems, markdown } = qualityReport({ ...ok, coverage: null, mutation: null });
    expect(problems).toEqual(['coverage: no report', 'mutation: no report']);
    expect(markdown).toContain('**Mutation score:** — (minimum 95%)');
  });

  it('exactly at a minimum is enough', () => {
    const edge = { total: { lines: { pct: 97 }, branches: { pct: 91 }, functions: { pct: 96 }, statements: { pct: 97 } } };
    expect(qualityReport({ ...ok, coverage: edge, mutation: 95 }).problems).toEqual([]);
  });
});

// Tests for the CI configuration itself (lesson 9.1): the real .github/workflows/test.yml must keep its promises.
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { parse } from 'yaml';
import { checkWorkflow } from './policy.js';

const TEXT = readFileSync(new URL('../../.github/workflows/test.yml', import.meta.url), 'utf8');
const { on, jobs } = parse(TEXT);
const PKG = JSON.parse(readFileSync(new URL('../../package.json', import.meta.url), 'utf8'));
const runs = (id) => jobs[id].steps.filter((s) => s.run).map((s) => s.run);

describe('.github/workflows/test.yml', () => {
  it.each(checkWorkflow(TEXT).map((r) => [r.id + ' ' + r.title, r]))('%s', (_, r) => {
    expect(r.why).toBe('');
  });

  it('runs on pull requests and on pushes to main', () => {
    expect(on.pull_request).toBeDefined();
    expect(on.push.branches).toEqual(['main']);
  });

  it('the unit job tests every Node version that package.json supports, and only those', () => {
    expect(PKG.engines.node).toBe('>=22.12');
    expect(jobs.unit.strategy.matrix.node).toEqual([22, 24]);
    expect(jobs.unit.strategy['fail-fast']).toBe(false);
  });

  it('the integration job uses the same PostgreSQL major version as production (17) and waits for it', () => {
    const pg = jobs.integration.services.postgres;
    expect(pg.image).toBe('postgres:17');
    expect(pg.options).toMatch(/--health-cmd "pg_isready -U postgres -d labflow_test"/);
    expect(jobs.integration.env.TEST_DATABASE_URL).toBe('postgres://postgres:test@localhost:5432/labflow_test');
  });

  it('e2e installs Chromium with its system libraries before running Playwright', () => {
    expect(runs('e2e')).toEqual(['npm ci', 'npx playwright install --with-deps chromium', 'npm run test:e2e']);
  });

  it('every test job uploads its reports, even when the tests are red', () => {
    const uploaders = Object.entries(jobs).filter(([, j]) => j.steps.some((s) => String(s.uses).startsWith('actions/upload-artifact@')));
    expect(uploaders.map(([id]) => id)).toEqual(['unit', 'integration', 'e2e', 'mutation']);
    const uploads = uploaders.flatMap(([, j]) => j.steps.filter((s) => String(s.uses).startsWith('actions/upload-artifact@')));
    expect(uploads.every((s) => s.if === '${{ !cancelled() }}')).toBe(true);
  });

  it('the gate requires exactly unit, integration, e2e, mutation and report (lesson 11.4)', () => {
    expect(jobs['ci-ok'].needs).toEqual(['unit', 'integration', 'e2e', 'mutation', 'report']);
    expect(jobs['ci-ok'].steps.at(-1).env.REQUIRED).toBe('unit,integration,e2e,mutation,report');
  });

  it('the report job reads every report, runs even after a red job, and keeps the exit code through tee', () => {
    const report = jobs.report;
    expect(report.if).toBe('${{ !cancelled() }}');
    expect(report.needs).toEqual(['unit', 'integration', 'e2e', 'mutation']);
    const names = report.steps.filter((s) => String(s.uses).startsWith('actions/download-artifact@')).map((s) => s.with.name);
    expect(names).toEqual(['unit-reports-node22', 'int-reports', 'e2e-reports', 'mutation-report']);
    const last = report.steps.at(-1);
    expect([last.shell, last.run]).toEqual(['bash', 'node scripts/ci-report.mjs | tee -a "$GITHUB_STEP_SUMMARY"']);
  });
});

// Rules every LabFlow Lite workflow must follow (lessons 9.1–9.4, graded in Lab 9 by scripts/cham-lab-9.mjs).
// Each rule reads the parsed YAML and says ok or why not. actionlint checks that a workflow is VALID;
// these rules check that it is SAFE: a red test must turn the required check red, and only a real bug may do that.
import { parse } from 'yaml';

const steps = (job) => job.steps ?? [];
const runs = (job) => steps(job).filter((s) => typeof s.run === 'string').map((s) => s.run);
const setupNode = (job) => steps(job).filter((s) => typeof s.uses === 'string' && s.uses.startsWith('actions/setup-node@'));
const nameOf = (id, job) => String(job.name ?? id);
const reportOnly = (job) => job['continue-on-error'] === true;
const needsOf = (job) => [job.needs ?? []].flat();
const gateOf = (jobs) => Object.entries(jobs).find(([id, job]) => nameOf(id, job) === 'ci-ok');

const RULES = [
  ['R1', 'npm ci, never npm install', (jobs) => {
    const bad = Object.entries(jobs).filter(([, j]) => runs(j).some((r) => /\bnpm (install|i)\b/.test(r))).map(([id]) => id);
    return bad.length ? 'npm install in: ' + bad.join(', ') + ' (it may change package-lock.json; CI must install exactly the lockfile)' : '';
  }],
  ['R2', 'setup-node caches the npm downloads', (jobs) => {
    const bad = Object.entries(jobs).filter(([, j]) => setupNode(j).some((s) => s.with?.cache !== 'npm')).map(([id]) => id);
    return bad.length ? 'no cache: npm in: ' + bad.join(', ') : '';
  }],
  ['R3', 'integration tests get a healthy PostgreSQL service', (jobs) => {
    const found = Object.entries(jobs).filter(([, j]) => runs(j).some((r) => r.includes('test:int')));
    if (!found.length) return 'no job runs npm run test:int';
    for (const [id, job] of found) {
      const pg = Object.values(job.services ?? {}).find((s) => /^postgres:17\b/.test(String(s.image)));
      if (!pg) return id + ': no postgres:17 service';
      if (!String(pg.options ?? '').includes('--health-cmd')) return id + ': the service has no --health-cmd, tests may start before PostgreSQL is ready';
      const url = String(job.env?.TEST_DATABASE_URL ?? steps(job).map((s) => s.env?.TEST_DATABASE_URL).find(Boolean) ?? '');
      const hostPorts = (pg.ports ?? []).map((p) => String(p).split(':')[0]);
      if (!hostPorts.some((p) => url.includes('@localhost:' + p + '/'))) return id + ': TEST_DATABASE_URL must reach the service at localhost:<published port>, got "' + url + '"';
    }
    return '';
  }],
  ['R4', 'Playwright browsers come with their system libraries', (jobs) => {
    const bad = Object.entries(jobs).filter(([, j]) => runs(j).some((r) => r.includes('playwright install') && !r.includes('--with-deps'))).map(([id]) => id);
    return bad.length ? 'playwright install without --with-deps in: ' + bad.join(', ') : '';
  }],
  ['R5', 'one gate job named exactly ci-ok', (jobs) => {
    const gate = gateOf(jobs);
    if (!gate) return 'no job is named ci-ok — branch protection needs one stable name to require';
    return /\$\{\{/.test(String(gate[1].name ?? '')) ? 'the gate name contains an expression' : '';
  }],
  ['R6', 'the gate runs even when a job it needs failed', (jobs) => {
    const gate = gateOf(jobs);
    if (!gate) return 'no ci-ok job';
    if (!/always\(\)|!\s*cancelled\(\)/.test(String(gate[1].if ?? ''))) return 'ci-ok has no if: always() — it is SKIPPED when a job fails, and a skipped required check counts as passed';
    const text = JSON.stringify(gate[1]);
